/** Markdown card projection, ported from idc_core/render.py. */

import { evaluateObligations } from './gates.js';

export function renderCard(state) {
  const header = state.task_id || `${state.record_id} (capture)`;
  const obligations = evaluateObligations(state, 'completed');
  const lines = [
    '<!-- AUTO-GENERATED by IDC from events.jsonl. Do not edit directly. -->',
    `# ${header}`,
    '',
    '## Current State',
    '',
    `- Lifecycle: \`${state.lifecycle}\``,
    `- Outcome: \`${state.outcome || 'open'}\``,
    `- Classifications: ${state.classifications.length ? state.classifications.join(', ') : 'unclassified'}`,
    `- Conditions: ${[...state.conditions].sort().join(', ') || 'none'}`,
    `- Activities: ${state.activities.length ? state.activities.join(', ') : 'none'}`,
    `- Learning: \`${state.learning_status}\``,
  ];
  if (!state.task_id) {
    let captureNote = `- Capture: \`${state.capture_mode}\``;
    if (state.expires_at) captureNote += ` (expires ${state.expires_at})`;
    lines.push(captureNote);
  }
  lines.push(
    '',
    '## Intent Translation',
    '',
    `- Goal: ${state.goal || state.summary}`,
    `- Explicit: ${joinList(state.explicit)}`,
    `- Repository facts: ${joinList(state.repository_facts)}`,
    `- Proposed defaults: ${joinList(state.proposed_defaults)}`,
    `- Open decisions: ${joinList(state.open_decisions)}`,
    '',
    '## Scope And Acceptance',
    '',
    `- Scope: ${joinList(state.scope)}`,
  );
  const passing = new Set();
  for (const evidence of state.evidence) {
    if (evidence.result === 'pass') {
      for (const acceptanceId of evidence.acceptance_ids ?? []) passing.add(acceptanceId);
    }
  }
  for (const item of state.acceptance) {
    const acceptanceId = item?.id ?? 'unknown';
    const marker = passing.has(acceptanceId) ? 'x' : ' ';
    lines.push(`- [${marker}] \`${acceptanceId}\` ${item?.statement ?? ''}`);
  }
  if (!state.acceptance.length) lines.push('- Acceptance: not recorded');
  lines.push('', '## Impact', '');
  for (const [name, level] of Object.entries(state.impacts).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
    lines.push(`- ${name}: \`${level}\``);
  }
  if (Object.keys(state.impacts).length === 0) lines.push('- Not assessed');
  lines.push('', '## Evidence', '');
  for (const evidence of state.evidence) {
    const mapped = (evidence.acceptance_ids ?? []).join(', ') || 'unmapped';
    lines.push(
      `- \`${evidence.kind ?? 'claimed'}\` / \`${evidence.result ?? 'unknown'}\` / ${mapped}: ${evidence.summary ?? ''}`,
    );
  }
  if (!state.evidence.length) lines.push('- None');
  lines.push('', '## Learning Review', '');
  if (state.learning_status === 'candidate') {
    for (const candidate of state.learning_candidates) {
      lines.push(
        `- \`${candidate.status ?? 'pending'}\` -> \`${candidate.destination ?? 'unknown'}\`: ${candidate.candidate ?? ''}`,
      );
    }
  } else if (state.learning_status === 'pending') {
    lines.push('- [ ] Review whether this task produced a reusable project lesson');
  } else {
    lines.push(`- \`${state.learning_status}\``);
  }
  lines.push('', '## Outstanding Obligations', '');
  for (const item of obligations.hard_blocks) lines.push(`- [ ] ${item}`);
  if (!obligations.hard_blocks.length) lines.push('- None');
  lines.push('', '## Event Log', '');
  for (const event of state.events) {
    lines.push(`- \`${event.timestamp}\` \`${event.type}\` (${event.provenance ?? 'claimed'})`);
  }
  return lines.join('\n') + '\n';
}

function joinList(values) {
  return values && values.length ? values.join('; ') : 'none';
}
